Pane</a></li><li class="leftmenu"><a href="/java-jscrollpane">Java JScrollPane</a></li><li class="leftmenu"><a href="/java-jsplitpane">Java JSplitPane</a></li><li class="leftmenu"><a href="/java-jtextpane">Java JTextPane</a></li><li class="leftmenu"><a href="/java-jrootpane">Java JRootPane</a></li><li class="leftmenu"><a href="/how-to-use-tooltip-in-java-swing">Using ToolTip</a></li><li class="leftmenu"><a href="/how-to-change-titlebar-icon-in-java-awt-swing">Change Title Icon</a></li><li class="leftmenu"><a href="/how-to-make-an-executable-jar-file-in-java">Executable Jar File</a></li><li class="leftmenu"><a href="/digital-watch">Digital Watch</a></li><li class="leftmenu"><a href="/Graphics-in-swing">Graphics in swing</a></li><li class="leftmenu"><a href="/Displaying-image-in-swing">Displaying Image</a></li></ul></div></div></div><div class="accordion-item" style="background-color:var(--sidebar)"><h2 class="accordion-header" id="flush-heading1"><button aria-controls="flush-collapse1" aria-expanded="true" class="accordion-button sidebar-btn" data-bs-target="#flush-collapse1" data-bs-toggle="collapse" type="button">Java Swing Apps</button></h2><div aria-labelledby="flush-heading1" class="accordion-collapse collapse show" id="flush-collapse1"><div class="accordion-body"><ul><li class="leftmenu"><a href="/notepad">Notepad</a></li><li class="leftmenu"><a href="/calculator-in-java">Calculator</a></li><li class="leftmenu"><a href="/ip-finder-in-java">IP Finder</a></li><li class="leftmenu"><a href="/word-count-in-java">Word Counter</a></li><li class="leftmenu"><a href="/url-source-code-generator-in-java">URL Source Generator</a></li><li class="leftmenu"><a href="/folder-explorer-in-java">Folder Explorer</a></li><li class="leftmenu"><a href="/Puzzle-Game">Puzzle Game</a></li><li class="leftmenu"><a href="/Pic-Puzzle-Game">Pic Puzzle Game</a></li><li class="leftmenu"><a href="/tic-tac-toe-game">Tic Tac Toe Game</a></li><li class="leftmenu"><a href="/online-exam-project-in-java-swing-without-database">Online Exam</a></li></ul></div></div></div><div class="accordion-item" style="background-color:var(--sidebar)"><h2 class="accordion-header" id="flush-heading2"><button aria-controls="flush-collapse2" aria-expanded="true" class="accordion-button sidebar-btn" data-bs-target="#flush-collapse2" data-bs-toggle="collapse" type="button">LayoutManagers</button></h2><div aria-labelledby="flush-heading2" class="accordion-collapse collapse show" id="flush-collapse2"><div class="accordion-body"><ul><li class="leftmenu"><a href="/java-layout-manager">BorderLayout</a></li><li class="leftmenu"><a href="/GridLayout">GridLayout</a></li><li class="leftmenu"><a href="/FlowLayout">FlowLayout</a></li><li class="leftmenu"><a href="/BoxLayout">BoxLayout</a></li><li class="leftmenu"><a href="/CardLayout">CardLayout</a></li><li class="leftmenu"><a href="/java-gridbaglayout">GridBagLayout</a></li><li class="leftmenu"><a href="/java-grouplayout">GroupLayout</a></li><li class="leftmenu"><a href="/java-springlayout">SpringLayout</a></li><li class="leftmenu"><a href="/java-scrollpanelayout">ScrollPaneLayout</a></li><li class="leftmenu"><a href="/layout-manager-in-java">Layout Manager in Java</a></li></ul></div></div></div></div></div></div><div class="col-12 col-md-7"><div class="overview"><div id="city"><table><tbody><tr><td><div id="bottomnextup"><a class="next" href="java-layout-manager">next&gt;&gt;</a> <a class="next" href="tic-tac-toe-game">&lt;&lt;prev</a></div><h1 class="h1">Online Exam Project in Java Swing without database</h1><div style="font-size:14px;margin-top:5px;margin-bottom:5px;color:#6f6e6e"><span>17 Mar 2025</span> | <span><i aria-hidden="true" class="fa fa-clock-o"></i> 2 min read</span></div><p>In this project, there are given 10 questions to play. User can bookmark any question for the reconsideration while going to result.</p><p>We are using here java array to store the questions, options and answers not database. You can use collection framework or database in place of array.</p><div class="codeblock"><textarea class="java" name="code">/*Online Java Paper Test*/

import java.awt.*;
import java.awt.event.*;
import javax.swing.*;

class OnlineTest extends JFrame implements ActionListener
{
	JLabel l;
	JRadioButton jb[]=new JRadioButton[5];
	JButton b1,b2;
	ButtonGroup bg;
	int count=0,current=0,x=1,y=1,now=0;
	int m[]=new int[10];	
	OnlineTest(String s)
	{
		super(s);
		l=new JLabel();
		add(l);
		bg=new ButtonGroup();
		for(int i=0;i&lt;5;i++)
		{
			jb[i]=new JRadioButton();	
			add(jb[i]);
			bg.add(jb[i]);
		}
		b1=new JButton("Next");
		b2=new JButton("Bookmark");
		b1.addActionListener(this);
		b2.addActionListener(this);
		add(b1);add(b2);
		set();
		l.setBounds(30,40,450,20);
		jb[0].setBounds(50,80,100,20);
		jb[1].setBounds(50,110,100,20);
		jb[2].setBounds(50,140,100,20);
		jb[3].setBounds(50,170,100,20);
		b1.setBounds(100,240,100,30);
		b2.setBounds(270,240,100,30);
		setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
		setLayout(null);
		setLocation(250,100);
		setVisible(true);
		setSize(600,350);
	}
	public void actionPerformed(ActionEvent e)
	{
		if(e.getSource()==b1)
		{
			if(check())
				count=count+1;
			current++;
			set();	
			if(current==9)
			{
				b1.setEnabled(false);
				b2.setText("Result");
			}
		}
		if(e.getActionCommand().equals("Bookmark"))
		{
			JButton bk=new JButton("Bookmark"+x);
			bk.setBounds(480,20+30*x,100,30);
			add(bk);
			bk.addActionListener(this);
			m[x]=current;
			x++;
			current++;
			set();	
			if(current==9)
				b2.setText("Result");
			setVisible(false);
			setVisible(true);
		}
		for(int i=0,y=1;i&lt;x;i++,y++)
		{
		if(e.getActionCommand().equals("Bookmark"+y))
		{
			if(check())
				count=count+1;
			now=current;
			current=m[y];
			set();
			((JButton)e.getSource()).setEnabled(false);
			current=now;
		}
		}
	
		if(e.getActionCommand().equals("Result"))
		{
			if(check())
				count=count+1;
			current++;
			//System.out.println("correct ans="+count);
			JOptionPane.showMessageDialog(this,"correct ans="+count);
			System.exit(0);
		}
	}
	void set()
	{
		jb[4].setSelected(true);
		if(current==0)
		{
			l.setText("Que1: Which one among these is not a primitive datatype?");
			jb[0].setText("int");jb[1].setText("Float");jb[2].setText("boolean");jb[3].setText("char");	
		}
		if(current==1)
		{
			l.setText("Que2: Which class is available to all the class automatically?");
			jb[0].setText("Swing");jb[1].setText("Applet");jb[2].setText("Object");jb[3].setText("ActionEvent");
		}
		if(current==2)
		{
			l.setText("Que3: Which package is directly available to our class without importing it?");
			jb[0].setText("swing");jb[1].setText("applet");jb[2].setText("net");jb[3].setText("lang");
		}
		if(current==3)
		{
			l.setText("Que4: String class is defined in which package?");
			jb[0].setText("lang");jb[1].setText("Swing");jb[2].setText("Applet");jb[3].setText("awt");
		}
		if(current==4)
		{
			l.setText("Que5: Which institute is best for java coaching?");
			jb[0].setText("Utek");jb[1].setText("Aptech");jb[2].setText("SSS IT");jb[3].setText("jtek");
		}
		if(current==5)
		{
			l.setText("Que6: Which one among these is not a keyword?");
			jb[0].setText("class");jb[1].setText("int");jb[2].setText("get");jb[3].setText("if");
		}
		if(current==6)
		{
			l.setText("Que7: Which one among these is not a class? ");
			jb[0].setText("Swing");jb[1].setText("Actionperformed");jb[2].setText("ActionEvent");
                        jb[3].setText("Button");
		}
		if(current==7)
		{
			l.setText("Que8: which one among these is not a function of Object class?");
			jb[0].setText("toString");jb[1].setText("finalize");jb[2].setText("equals");
                        jb[3].setText("getDocumentBase");		
		}
		if(current==8)
		{
			l.setText("Que9: which function is not present in Applet class?");
			jb[0].setText("init");jb[1].setText("main");jb[2].setText("start");jb[3].setText("destroy");
		}
		if(current==9)
		{
			l.setText("Que10: Which one among these is not a valid component?");
			jb[0].setText("JButton");jb[1].setText("JList");jb[2].setText("JButtonGroup");
                        jb[3].setText("JTextArea");
		}
		l.setBounds(30,40,450,20);
		for(int i=0,j=0;i&lt;=90;i+=30,j++)
			jb[j].setBounds(50,80+i,200,20);
	}
	boolean check()
	{
		if(current==0)
			return(jb[1].isSelected());
		if(current==1)
			return(jb[2].isSelected());
		if(current==2)
			return(jb[3].isSelected());
		if(current==3)
			return(jb[0].isSelected());
		if(current==4)
